import importlib.util
import json
from pathlib import Path


def test_precompiles_lists_nested_abi_dirs():
    generator_path = Path(__file__).with_name("gen_system_docs.py")
    spec = importlib.util.spec_from_file_location("gen_system_docs", generator_path)
    assert spec is not None
    assert spec.loader is not None
    generator = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(generator)

    filename, text = generator.gen_precompiles()

    assert filename == "precompiles.md"
    assert text.startswith(
        "<!-- Generated by tools/docs/gen-system-docs.sh. Do not edit by hand. -->\n\n"
        "# Precompile ABIs\n\n"
    )
    summary = text.split("\n## Summary\n\n", 1)[1].split("\n## ", 1)[0]
    for name, address in (
        ("perps", "0x0000000000000000000000000000000000001015"),
        ("pricefeed", "0x0000000000000000000000000000000000001020"),
    ):
        assert f"| {name} | `precompiles/{name}/abi/abi.json` | `{address}` |" in summary
        assert f"\n## {name} (`abi.json`)\n\nAddress: `{address}`\n" in text

    assert (
        "| addr | `precompiles/addr/abi.json` | `0x0000000000000000000000000000000000001004` |"
        in summary
    )
    preserved = (generator.ROOT / "docs/system" / filename).read_text(encoding="utf-8")
    assert preserved.startswith(
        "<!-- Preserve the lifecycle and address-selection notes when refreshing ABI signatures. -->\n\n"
        "# Precompile ABIs\n\n"
    )
    preserved_summary = preserved.split("\n## Summary\n\n", 1)[1].split("\n## ", 1)[0]
    for name, source, address in (
        (
            "perps",
            "precompiles/perps/abi/abi.json",
            "0x0000000000000000000000000000000000001015",
        ),
        (
            "pricefeed",
            "precompiles/pricefeed/abi/abi.json",
            "0x0000000000000000000000000000000000001020",
        ),
        (
            "addr",
            "precompiles/addr/abi.json",
            "0x0000000000000000000000000000000000001004",
        ),
    ):
        entries = json.loads((generator.ROOT / source).read_text(encoding="utf-8"))
        count = sum(entry.get("type") == "function" for entry in entries)
        assert count > 0
        assert (
            f"| {name} | [`{source}`](../../{source}) | `{address}` | {count} |"
            in preserved_summary
        )
        section = preserved.split(f"\n## {name} (`abi.json`)\n\n", 1)[1].split(
            "\n## ", 1
        )[0]
        assert f"Source: [`{source}`](../../{source}).\n" in section
        assert f"Destination: `{address}`.\n" in section
        for entry in entries:
            if entry.get("type") in ("function", "event", "error"):
                assert f"- `{generator.abi_signature(entry)}`" in section
